From 354d599d36cb2a6799a999bd052e0ede37505c62 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 21:37:29 +0100
Subject: [PATCH] plasma-shutdown: ask for authentication before ending the
 session

When polkit requires a password to reboot or power off, logind asked for
it only after the session and its polkit agent were gone, so it failed
and left a black screen. Now we ask before ending the session instead.

BUG: 477056
---
 startkde/plasma-shutdown/shutdown.cpp | 56 ++++++++++++++++++++++++++-
 startkde/plasma-shutdown/shutdown.h   |  4 ++
 2 files changed, 58 insertions(+), 2 deletions(-)

diff --git a/startkde/plasma-shutdown/shutdown.cpp b/startkde/plasma-shutdown/shutdown.cpp
index af56314186..369ff9eb58 100644
--- a/startkde/plasma-shutdown/shutdown.cpp
+++ b/startkde/plasma-shutdown/shutdown.cpp
@@ -3,6 +3,7 @@

 #include <QCoreApplication>
 #include <QDBusConnection>
+#include <QDBusUnixFileDescriptor>
 #include <QDir>
 #include <QProcess>
 #include <QStandardPaths>
@@ -15,6 +16,13 @@

 #include "config.h"

+using namespace Qt::StringLiterals;
+
+static QDBusMessage login1Call(const QString &method)
+{
+    return QDBusMessage::createMethodCall(u"org.freedesktop.login1"_s, u"/org/freedesktop/login1"_s, u"org.freedesktop.login1.Manager"_s, method);
+}
+
 Shutdown::Shutdown(QObject *parent)
     : QObject(parent)
 {
@@ -124,7 +132,7 @@ void Shutdown::ksmServerComplete()
             return;
         }
         if (reply.value()) {
-            logoutComplete();
+            authorizeShutdown();
         } else {
             ksmserverIface.resetLogout();
             logoutCancelled();
@@ -132,6 +140,46 @@ void Shutdown::ksmServerComplete()
     });
 }

+void Shutdown::authorizeShutdown()
+{
+    if (m_shutdownType != ShutdownTypeHalt && m_shutdownType != ShutdownTypeReboot) {
+        logoutComplete();
+        return;
+    }
+    const QString action = m_shutdownType == ShutdownTypeHalt ? u"PowerOff"_s : u"Reboot"_s;
+    const QDBusReply<QString> canReply = QDBusConnection::systemBus().call(login1Call(u"Can"_s + action));
+    if (!canReply.isValid() || canReply.value() != u"challenge") {
+        logoutComplete();
+        return;
+    }
+
+    // logind asks for authentication through the session's polkit agent, which is gone once the session has ended,
+    // so ask now and hold a delay lock that keeps logind waiting until the session is down
+    QDBusMessage inhibit = login1Call(u"Inhibit"_s);
+    inhibit << u"shutdown"_s << u"Plasma"_s << u"Ending the session"_s << u"delay"_s;
+    const QDBusReply<QDBusUnixFileDescriptor> lockReply = QDBusConnection::systemBus().call(inhibit);
+    if (lockReply.isValid()) {
+        m_shutdownLock = lockReply.value();
+    }
+
+    QDBusMessage request = login1Call(action);
+    request << true;
+    auto watcher = new QDBusPendingCallWatcher(QDBusConnection::systemBus().asyncCall(request, INT32_MAX), this);
+    connect(watcher, &QDBusPendingCallWatcher::finished, this, [this](QDBusPendingCallWatcher *watcher) {
+        watcher->deleteLater();
+        if (watcher->isError()) {
+            qCWarning(PLASMA_SESSION) << "Shutdown was not authorized:" << watcher->error().message();
+            m_shutdownLock = QDBusUnixFileDescriptor();
+            OrgKdeKSMServerInterfaceInterface ksmserverIface(QStringLiteral("org.kde.ksmserver"), QStringLiteral("/KSMServer"), QDBusConnection::sessionBus());
+            ksmserverIface.resetLogout();
+            logoutCancelled();
+            return;
+        }
+        m_shutdownAuthorized = true;
+        logoutComplete();
+    });
+}
+
 void Shutdown::logoutCancelled()
 {
     m_shutdownType = ShutdownTypeNone;
@@ -184,7 +232,11 @@ void Shutdown::logoutComplete()
         reply.waitForFinished();
     }

-    if (m_shutdownType == ShutdownTypeHalt) {
+    if (m_shutdownAuthorized) {
+        // logind goes on with the shutdown once the delay lock is released
+        m_shutdownLock = QDBusUnixFileDescriptor();
+        qApp->quit();
+    } else if (m_shutdownType == ShutdownTypeHalt) {
         SessionBackend::self()->shutdown();
     } else if (m_shutdownType == ShutdownTypeReboot) {
         SessionBackend::self()->reboot();
diff --git a/startkde/plasma-shutdown/shutdown.h b/startkde/plasma-shutdown/shutdown.h
index 8bfe0ce1e6..f794e7c4a1 100644
--- a/startkde/plasma-shutdown/shutdown.h
+++ b/startkde/plasma-shutdown/shutdown.h
@@ -8,6 +8,7 @@

 #pragma once

+#include <QDBusUnixFileDescriptor>
 #include <QObject>

 enum ShutdownType {
@@ -33,8 +34,11 @@ private Q_SLOTS:

 private:
     void startLogout(ShutdownType shutdownType);
+    void authorizeShutdown();
     void runShutdownScripts();
     bool usingSystemdManagedSession();
     // ShutdownTypeNone means idle, see startLogout().
     ShutdownType m_shutdownType = ShutdownTypeNone;
+    bool m_shutdownAuthorized = false;
+    QDBusUnixFileDescriptor m_shutdownLock;
 };
